issues.test_scenario:
def test_product_images_load_successfully(page):
    page.goto('http://localhost:8000/demo/broken_page.html')
    images = page.locator('.card-img-wrap img').all()
    for idx, img in enumerate(images):
        is_loaded = page.evaluate('(el) => el.complete && el.naturalWidth > 0', img.element_handle())
        assert is_loaded, f'Image index {idx} failed to render or has broken source'

def test_form_inputs_have_accessible_labels(page):
    page.goto('http://localhost:8000/demo/broken_page.html')
    inputs = page.locator('.newsletter-form input').all()
    for inp in inputs:
        has_label = page.evaluate('''(el) => {
            const id = el.id;
            const hasForLabel = id ? !!document.querySelector(`label[for="${id}"]`) : false;
            const hasAria = el.getAttribute('aria-label') || el.getAttribute('aria-labelledby');
            const hasPlaceholder = el.getAttribute('placeholder');
            return !!(hasForLabel || hasAria || hasPlaceholder);
        }''', inp.element_handle())
        assert has_label, 'Input field lacks accessible label or placeholder'

