issues.test_scenario:
def test_cta_button_text_not_clipped(page):
    page.goto('http://localhost:8000/demo/broken_page.html')
    is_clipped = page.evaluate("() => {
        const btn = document.querySelector('.cta-button-clipped');
        return btn.scrollWidth > btn.clientWidth;
    }")
    assert not is_clipped, 'CTA button text is clipped by its bounding container!'

